import { useState } from 'react';
import './notification.css';

function Notification({ userName, userRole, taskStats, onUnreadChange }) {
	const [notifications, setNotifications] = useState([
		{ id: 1, title: 'Welcome to your workspace', text: `Your ${userRole.toLowerCase()} dashboard is ready, ${userName}.`, time: 'Just now', unread: true, type: 'workspace' },
		{ id: 2, title: taskStats.remaining ? `${taskStats.remaining} tasks need attention` : 'All tasks are complete', text: taskStats.remaining ? 'Review your active tasks before the end of the day.' : 'You are up to date with your current workload.', time: 'Today', unread: true, type: 'task' },
		{ id: 3, title: userRole === 'Admin' ? 'Workspace overview available' : 'Workspace update', text: userRole === 'Admin' ? 'Review users and their assigned tasks from Manage Users.' : 'Check your latest task assignments.', time: 'Today', unread: true, type: 'info' },
	]);

	function updateNotifications(nextNotifications) {
		setNotifications(nextNotifications);
		onUnreadChange(nextNotifications.filter((notification) => notification.unread).length);
	}

	function markAsRead(notificationId) {
		updateNotifications(notifications.map((notification) => notification.id === notificationId ? { ...notification, unread: false } : notification));
	}

	function markAllAsRead() {
		updateNotifications(notifications.map((notification) => ({ ...notification, unread: false })));
	}

	return (
		<section className="notification-page" aria-labelledby="notification-title">
			<div className="notification-heading">
				<div><p className="dashboard-label">Workspace updates</p><h2 id="notification-title">Notifications</h2><p>Stay up to date with your tasks and workspace.</p></div>
				<button className="notification-clear-button" type="button" onClick={markAllAsRead}>Mark all as read</button>
			</div>
			<div className="notification-list">
				{notifications.map((notification) => <article className={`notification-item ${notification.unread ? 'unread' : ''}`} key={notification.id}><span className={`notification-type ${notification.type}`} aria-hidden="true">{notification.type === 'task' ? '!' : notification.type === 'workspace' ? 'W' : 'i'}</span><div className="notification-copy"><h3>{notification.title}</h3><p>{notification.text}</p><small>{notification.time}</small></div>{notification.unread && <button className="notification-read-button" type="button" onClick={() => markAsRead(notification.id)}>Mark read</button>}</article>)}
			</div>
		</section>
	);
}

export default Notification;
